{
  "model": "z-ai/glm-5.1",
  "messages": [
    {
      "role": "system",
      "content": "你是一个智能助手，可以查询天气信息。"
    },
    {
      "role": "user",
      "content": "我想知道北京的天气。"
    },
    {
      "role": "assistant",
      "content": "好的，请问您想查询哪一天的天气？"
    },
    {
      "role": "user",
      "content": "今天。"
    },
    {
      "role": "assistant",
      "content": "稍等，我为您调用天气工具查询"
    },
    {
      "role": "user",
      "content": "北京今天天气怎么样？asaaaaaa"
    }
  ],
  "temperature": 0.7,
  "max_tokens": 4096,
  "stream": false,
  "top_p": 0.9,
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "get_weather",
        "description": "获取指定城市的天气信息",
        "parameters": {
          "type": "object",
          "properties": {
            "city": {
              "type": "string",
              "description": "城市名称"
            }
          },
          "required": ["city"]
        }
      }
    }
  ],
  "tool_choice": "auto"
}
